#!/usr/bin/env python3
import base64, os, sys, shutil
from pathlib import Path
from datetime import datetime

def root():
    if sys.platform == "win32":
        return Path(os.environ.get("USERPROFILE", str(Path.home()))) / "Documents" / "FXJEFE_Project"
    return Path.home() / "Documents" / "FXJEFE_Project"
FILES = {
  'feature_registry.py': b'',
  'pipelinerun_production.py': b'',
}
r = root()
for name, b64 in FILES.items():
    dest = r / name
    if dest.exists():
        bak = dest.with_suffix(dest.suffix + ".bak_" + datetime.now().strftime("%Y%m%d%H%M%S"))
        shutil.copy2(dest, bak)
        print("backup", bak.name)
    dest.write_bytes(base64.b64decode(b64))
    print("updated", dest)
import subprocess
subprocess.run([sys.executable, "-m", "py_compile", str(r / "feature_registry.py")])
print("OK — now run:")
print("  cd", r)
print("  python3 pipelinerun_production.py")
